import{z as s,x as o,o as B,c as i,q as e,j as A,D as E,d as r,s as n,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"并行回测","description":"","frontmatter":{"title":"并行回测","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-parallel-backtest.md","filePath":"quant/bf-parallel-backtest.md","lastUpdated":1791413859000}'),p={name:"quant/bf-parallel-backtest.md"};function d(D,a,h,C,m,u){const t=o("Mermaid");return B(),i("div",null,[a[2]||(a[2]=e('<h1 id="并行回测" tabindex="-1">并行回测 <a class="header-anchor" href="#并行回测" aria-label="Permalink to &quot;并行回测&quot;">​</a></h1><div class="epigraph"><p>并行只许改变速度，不许改变答案：任何一段历史的净值，不能依赖它与别的段谁先算完。</p><footer>—— 据 Dean and Ghemawat, MapReduce: Simplified Data Processing on Large Clusters, OSDI 2004 对无共享并行与确定性归并的论述；对照回放确定性要求整理</footer></div><p><a href="/quant/bf-param-sweep-arch">上一课</a>把扫描变成任务与结果库；千个配置乘十年历史超出单核，本课写并行回测的三条轴——按配置、按时间段、按资产组——以及每条轴上的确定性与边界条件。第一课的解剖在此约束设计：全序事件流可以分段喂给多个引擎进程，但每段内部的因果不变量一点也不能松。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>天真的并行以三种方式改变答案。共享随机数源让结果依赖工作进程数与调度顺序，上一课的「同一身份重放必得同一结果」被打破；时间段切分不做预热，每段开头在冷状态上交易——仓位为零、指标未热——合并后的净值带着系统性坑洼；按资产切分对横截面策略致命：排序与中性化需要全宇宙同时在场，拆开算的截面排名不是截面排名。第四种更隐蔽：部分失败的工作进程被聚合层当成已完成，报告的分布悄悄缺了一角。</p><h3 id="三条轴与各自的合法性" tabindex="-1">三条轴与各自的合法性 <a class="header-anchor" href="#三条轴与各自的合法性" aria-label="Permalink to &quot;三条轴与各自的合法性&quot;">​</a></h3><p><strong>按配置</strong>最干净：配置之间无共享状态，天然无共享并行；主进程把主种子派生为每配置的独立种子流，工作进程从只读数据存储读数（<a href="/quant/de-tsdb-selection">时序数据库的选型</a>的分区即为此设计），结果按试验身份写回——身份相同覆盖也幂等，重试因此安全。<strong>按时间段</strong>要过两道边界：预热长度取信号最长回看期加 purge/embargo（与<a href="/quant/purge-embargo">Embargo 与 Purge</a> 同一算术），前一段的末状态作为后一段的初始状态显式交接。<strong>按资产组</strong>只在无跨资产约束时合法；横截面排名须两阶段——特征并行算、排名集中做——否则并行的不只是计算，还有答案。</p>',7)),(B(),A(l,null,{default:E(()=>[n(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20MST%5B%22%E4%B8%BB%E8%BF%9B%E7%A8%8B%20%E4%BB%BB%E5%8A%A1%E8%A1%A8%E4%B8%8E%E7%A7%8D%E5%AD%90%E6%B4%BE%E7%94%9F%22%5D%20--%3E%20W1%5B%22%E5%B7%A5%E4%BD%9C%E8%BF%9B%E7%A8%8B%20%E9%85%8D%E7%BD%AEA%20%E6%97%B6%E9%97%B4%E6%AE%B51%20%E5%90%AB%E9%A2%84%E7%83%AD%22%5D%0A%20%20MST%20--%3E%20W2%5B%22%E5%B7%A5%E4%BD%9C%E8%BF%9B%E7%A8%8B%20%E9%85%8D%E7%BD%AEA%20%E6%97%B6%E9%97%B4%E6%AE%B52%20%E6%8E%A5%E5%88%9D%E5%A7%8B%E7%8A%B6%E6%80%81%22%5D%0A%20%20MST%20--%3E%20W3%5B%22%E5%B7%A5%E4%BD%9C%E8%BF%9B%E7%A8%8B%20%E9%85%8D%E7%BD%AEB%20%E6%97%B6%E9%97%B4%E6%AE%B51%22%5D%0A%20%20W1%20--%3E%20HS%5B%22%E6%AE%B5%E6%9C%AB%E7%8A%B6%E6%80%81%E4%BA%A4%E6%8E%A5%22%5D%0A%20%20HS%20--%3E%20W2%0A%20%20W1%20--%3E%20ST%5B%22%E7%BB%93%E6%9E%9C%E5%BA%93%20%E6%8C%89%E8%BA%AB%E4%BB%BD%E5%B9%82%E7%AD%89%E5%86%99%22%5D%0A%20%20W2%20--%3E%20ST%0A%20%20W3%20--%3E%20ST%0A%20%20ST%20--%3E%20VF%7B%22%E4%B8%8D%E5%90%8C%E8%BF%9B%E7%A8%8B%E6%95%B0%E9%87%8D%E6%94%BE%20%E7%BB%93%E6%9E%9C%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20VF%20--%3E%7C%E5%90%A6%7C%20FIX%5B%22%E4%BF%AE%E7%A7%8D%E5%AD%90%E6%B5%81%E4%B8%8E%E5%BD%92%E5%B9%B6%E5%BA%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>确定性是并行回测的验收标准，写法是：同一身份在 \\(1\\)、\\(8\\)、\\(32\\) 个进程下各跑一遍，结果库逐字节一致（或声明浮点容差并固定归并顺序）。做不到，先查三处：共享随机源、浮点归并顺序、依赖墙钟的日志字段。任务表由主进程下发，工作进程无状态；失败重试因为幂等写而无需协调。聚合层必须核对任务表与结果库的差集，缺一格就整批标记不完整——补齐失败的格子，而不是假装分布完整。</p><p><span class="marginnote">浮点求和的顺序改变最后几位小数；若策略里有「收益大于阈值就调仓」这类判断，最后几位偶尔会翻转决策。并行版本与单机版本对不上时，先对到事件流逐条一致，再谈容差——容差是为测量定的，不是为掩盖顺序差定的。</span></p><p><span class="marginnote">「幂等写」就是同一个结果写两遍，库里仍然只有一条且内容不变。这为什么重要：云上工作进程随时可能被抢占，任务重跑后结果是覆盖而不是追加成两条，聚合层就不必区分「第一次算」与「重试」——重试安全是设计出来的，不是求出来的。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>并行的收益算术决定架构。事件引擎单核一天日内数据常以秒计，二十年乘千配置就是机器年级别——必须分布；而分布式后第一个瓶颈往往不是计算，是数据分发：全量 tick 广播给每个工作进程，网络先饱和。解法是存储端分区加工作进程就近读，让数据移动一次而不是每任务一次。调度器保持愚蠢是 MapReduce 以来的成熟经验：主进程只管派任务、收结果、核对差集，不参与计算语义；这样扩展性的 reasoning 才停留在任务表层面，不污染引擎。</p>',6)),(B(),A(l,null,{default:E(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20DS%5B%22%E8%A1%8C%E6%83%85%E5%AD%98%E5%82%A8%20%E6%8C%89%E6%97%A5%E6%9C%9F%E4%B8%8E%E5%90%88%E7%BA%A6%E5%88%86%E5%8C%BA%22%5D%20--%3E%7C%22%E6%95%B0%E6%8D%AE%E5%8F%AA%E7%A7%BB%E5%8A%A8%E4%B8%80%E6%AC%A1%22%7C%20C1%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%20%E5%88%86%E5%8C%BAA%22%5D%0A%20%20DS%20--%3E%20C2%5B%22%E6%9C%AC%E5%9C%B0%E7%BC%93%E5%AD%98%20%E5%88%86%E5%8C%BAB%22%5D%0A%20%20C1%20--%3E%20W1%5B%22%E5%B7%A5%E4%BD%9C%E8%BF%9B%E7%A8%8B%20%E5%B0%B1%E8%BF%91%E8%AF%BB%E6%95%B0%22%5D%0A%20%20C2%20--%3E%20W2%5B%22%E5%B7%A5%E4%BD%9C%E8%BF%9B%E7%A8%8B%20%E5%B0%B1%E8%BF%91%E8%AF%BB%E6%95%B0%22%5D%0A%20%20W1%20--%3E%20AG%5B%22%E8%81%9A%E5%90%88%E5%B1%82%20%E6%A0%B8%E5%AF%B9%E4%BB%BB%E5%8A%A1%E8%A1%A8%E5%B7%AE%E9%9B%86%22%5D%0A%20%20W2%20--%3E%20AG%0A%20%20AG%20--%3E%7C%22%E7%BC%BA%E4%B8%80%E6%A0%BC%22%7C%20MK%5B%22%E6%95%B4%E6%89%B9%E6%A0%87%E8%AE%B0%E4%B8%8D%E5%AE%8C%E6%95%B4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p><span class="marginnote">给个数量级：一段日内 tick 行情一天可达数十 GB，若每个任务都把全量数据拉一遍，千个配置就是数十 TB 的重复搬运；按日期与合约分区后，每个工作进程只读自己那一段。瓶颈从「算得慢」变成「搬得慢」时，该省的是网络，不是再堆 CPU。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>并行不适用于所有维度：自适应搜索（贝叶斯优化）天然串行，并行的是评估不是搜索；单场所事件全序本身不可并行化——按场所分片到进程可以，场所内部仍须有序，与<a href="/quant/matching-engine-arch">撮合引擎架构</a>对真引擎的约束一致。抢占式云机的中断用段级断点恢复，不靠进程长命。最后，并行放大的是吞吐不是证据：\\(N\\) 的计数、成本情景、数据版本都沿用上一课的定义，多核不产生新假设。</p><p><span class="marginnote">初学者容易把「跑得快」当成「更有说服力」——一千个回测并行跑完，证据并没有比一个多。每个格子用的仍是同一份数据、同一套成本假设；如果数据有泄漏，三十二个核只是更快地算出同一个错误答案。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三条轴：按配置（无共享、种子派生）、按时间段（预热加状态交接）、按资产组（横截面须集中排名）。</li><li>确定性验收：不同进程数重放同一身份，结果逐条一致；先查随机源与归并序。</li><li>段边界算术与 purge-embargo 一致；冷状态坑洼是切段并行的头号伪造。</li><li>调度器保持愚蠢，幂等写使重试安全；聚合层核对差集，缺格不报完整。</li><li>出处：Dean and Ghemawat, <em>OSDI</em>, 2004；站内<a href="/quant/bf-param-sweep-arch">参数扫描的架构</a>、<a href="/quant/purge-embargo">Embargo 与 Purge</a>、<a href="/quant/matching-engine-arch">撮合引擎架构</a>各课。</li></ul>',6))])}const f=s(p,[["render",d]]);export{_ as __pageData,f as default};
